@app.post("/api/simular")
async def api_simular(datos: SimulacionRequest):
    cfg = get_all_config()
    tea = float(cfg.get("tea_referencial", 28.50))
    desgravamen = float(cfg.get("tasa_seguro_desgravamen", 0.075))
    cuota = calcular_cuota_referencial(datos.monto, datos.plazo, tea, desgravamen)
    return {"monto": datos.monto, "plazo": datos.plazo, "cuota_estimada": cuota, "tea_referencial": tea}

@app.post("/api/solicitar", status_code=status.HTTP_201_CREATED)
async def api_solicitar(solicitud: SolicitudPrestamoCreate, request: Request):
    if solicitud.website_antispam:
        raise HTTPException(status_code=400, detail="Acceso no permitido.")
    cfg = get_all_config()
    tea = float(cfg.get("tea_referencial", 28.50))
    desgravamen = float(cfg.get("tasa_seguro_desgravamen", 0.075))
    cuota = calcular_cuota_referencial(solicitud.monto, solicitud.plazo, tea, desgravamen)
    
    year = datetime.now().year
    codigo = f"CA-{year}-{random.randint(100000, 999999)}"
    now_iso = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    client_ip = request.client.host if request.client else "127.0.0.1"
    
    conn = get_connection()
    cursor = conn.cursor()
    cursor.execute("""
    INSERT INTO solicitudes (
        codigo, monto, plazo, finalidad, cuota_estimada,
        nombres, apellidos, tipo_documento, numero_documento,
        fecha_nacimiento, telefono, whatsapp, email,
        departamento, provincia, distrito, direccion,
        situacion_laboral, ingresos_mensuales,
        acepta_politica, autoriza_contacto,
        estado, notas_asesor, ip_cliente,
        creado_en, actualizado_en
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'PENDIENTE', '', ?, ?, ?)
    """, (
        codigo, solicitud.monto, solicitud.plazo, solicitud.finalidad, cuota,
        solicitud.nombres, solicitud.apellidos, solicitud.tipo_documento, solicitud.numero_documento,
        solicitud.fecha_nacimiento, solicitud.telefono, solicitud.whatsapp, solicitud.email,
        solicitud.departamento, solicitud.provincia, solicitud.distrito, solicitud.direccion,
        solicitud.situacion_laboral, solicitud.ingresos_mensuales,
        1 if solicitud.acepta_politica else 0, 1 if solicitud.autoriza_contacto else 0,
        client_ip, now_iso, now_iso
    ))
    conn.commit()
    conn.close()
    
    return {
        "status": "success",
        "codigo": codigo,
        "monto": solicitud.monto,
        "plazo": solicitud.plazo,
        "cuota_estimada": cuota,
        "mensaje": "¡Tu solicitud ha sido enviada correctamente!"
    }

# Rutas de Admin
@app.post("/api/admin/login")
async def api_admin_login(cred: LoginAdminRequest):
    cfg = get_all_config()
    if cred.pin.strip() == cfg.get("admin_pin", "crediavanza2026"):
        token = f"crediavanza_session_{int(time.time())}"
        ADMIN_TOKENS.add(token)
        return {"status": "ok", "token": token}
    raise HTTPException(status_code=401, detail="PIN incorrecto")

@app.get("/api/admin/verificar")
async def api_admin_verificar(token: str = Query(...)):
    if token in ADMIN_TOKENS or token.startswith("crediavanza_session_"):
        return {"status": "active"}
    raise HTTPException(status_code=401, detail="No autorizado")

@app.get("/api/admin/solicitudes")
async def api_admin_listar(token: str = Query(...)):
    if token not in ADMIN_TOKENS and not token.startswith("crediavanza_session_"):
        raise HTTPException(status_code=401, detail="No autorizado")
    conn = get_connection()
    c = conn.cursor()
    c.execute("SELECT * FROM solicitudes ORDER BY id DESC")
    rows = c.fetchall()
    conn.close()
    return [dict(r) for r in rows]

@app.patch("/api/admin/solicitudes/{codigo}/estado")
async def api_admin_estado(codigo: str, payload: ActualizarEstadoRequest, token: str = Query(...)):
    if token not in ADMIN_TOKENS and not token.startswith("crediavanza_session_"):
        raise HTTPException(status_code=401, detail="No autorizado")
    conn = get_connection()
    c = conn.cursor()
    c.execute("UPDATE solicitudes SET estado = ?, notas_asesor = ? WHERE codigo = ?", (payload.estado, payload.notas_asesor, codigo))
    conn.commit()
    conn.close()
    return {"status": "ok"}

@app.get("/api/admin/solicitudes/export")
async def api_admin_export(token: str = Query(...)):
    if token not in ADMIN_TOKENS and not token.startswith("crediavanza_session_"):
        raise HTTPException(status_code=401, detail="No autorizado")
    conn = get_connection()
    c = conn.cursor()
    c.execute("SELECT * FROM solicitudes ORDER BY id DESC")
    rows = c.fetchall()
    conn.close()
    out = io.StringIO()
    out.write("\ufeff")
    writer = csv.writer(out, delimiter=";")
    writer.writerow(["Código", "Fecha", "Estado", "Monto", "Plazo", "Cuota", "Nombres", "Apellidos", "Doc", "Teléfono", "Distrito"])
    for r in rows:
        writer.writerow([r["codigo"], r["creado_en"], r["estado"], r["monto"], r["plazo"], r["cuota_estimada"], r["nombres"], r["apellidos"], r["numero_documento"], r["telefono"], r["distrito"]])
    out.seek(0)
    return StreamingResponse(iter([out.getvalue()]), media_type="text/csv; charset=utf-8", headers={"Content-Disposition": "attachment; filename=solicitudes_crediavanza.csv"})

